const sessionId = typeof $json.sessionId === 'string' ? $json.sessionId.trim() : '';
const requestId = typeof $json.requestId === 'string' ? $json.requestId.trim() : '';
const uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const error = (uuidPattern.test(sessionId) && uuidPattern.test(requestId))
  ? null
  : { code: 'INVALID_SESSION', message: 'Checking the Xero connection needs a valid conversation and request ID.' };
return [{ json: {
  valid: error === null, sessionId, requestId,
  proposedInput: { sessionId, requestId },
  ...(error ? { response: { ok: false, error } } : {}),
} }];

const raw = $input.first().json ?? {};
const status = Number(raw.statusCode ?? 0);
const body = raw.body ?? {};
// No credential selected at all: n8n fails the node rather than returning a
// status, and onError passes the item through with `error` set.
const nodeError = String(raw.error?.message ?? raw.error ?? '');

const CONNECT_STEPS = "Open n8n at http://localhost:5678 | Go to Credentials and open the one named \"Xero (read-only)\". If it is not there yet it has to be created once, and it needs a Xero developer app first: docs/XERO_RECONCILIATION.md has every click. | Select Connect my account. Xero opens its own sign-in and permission window. | Grant access. The permission screen should say the app wants to view your accounting data. If it offers to create, update or delete anything, stop: the Scope field is wrong.";

const orgs = Array.isArray(body) ? body : [];
let state = 'unknown';
let message = '';

if (status === 200 && orgs.length > 0) {
  state = 'connected';
  message = `Xero is connected to ${orgs[0].tenantName}.`;
} else if (status === 200) {
  state = 'not_connected';
  message = 'Xero answered, but no organisation has been authorised for this connection yet.';
} else if (status === 401 || status === 403) {
  state = 'needs_reauth';
  message = 'Xero is set up but is refusing the connection. A Xero refresh token stops working after 60 days without use, so this is usually just a reconnect.';
} else if (!status || /credential/i.test(nodeError)) {
  state = 'not_connected';
  message = 'There is no working Xero connection yet. It has to be created once in n8n; it cannot be done from this chat.';
} else {
  state = 'unknown';
  message = `Xero did not answer as expected (${status || 'no response'}). It may be a temporary network problem.`;
}

return [{ json: {
  connected: state === 'connected',
  state,
  message,
  organisationName: state === 'connected' ? String(orgs[0].tenantName ?? '') : '',
  tenantId: state === 'connected' ? String(orgs[0].tenantId ?? '') : '',
  organisationCount: orgs.length,
  n8nUrl: 'http://localhost:5678',
  connectSteps: CONNECT_STEPS,
  scope: 'offline_access accounting.transactions.read accounting.contacts.read accounting.settings.read accounting.reports.read',
} }];

const raw = $input.first().json ?? {};
const status = Number(raw.statusCode ?? 0);
const body = raw.body ?? {};
const nodeError = String(raw.error?.message ?? raw.error ?? '');
const WRITE_CONNECT_STEPS = "This one is optional. Everything except preparing transactions works without it. | In n8n, Credentials, create a second credential of type OAuth2 API named exactly \"Xero (read-write)\", using the same Xero app as the first. | Set the Scope field to: offline_access accounting.transactions | Select Connect my account. This permission screen will say view AND update your business transactions. That difference is the whole point of the second credential, and you should never see those words on the read-only one.";

const orgs = Array.isArray(body) ? body : [];
let writeState = 'unknown';
if (status === 200 && orgs.length > 0) writeState = 'connected';
else if (status === 401 || status === 403) writeState = 'needs_reauth';
else if (!status || /credential/i.test(nodeError)) writeState = 'not_connected';

return [{ json: {
  writeState,
  writeConnected: writeState === 'connected',
  writeConnectSteps: WRITE_CONNECT_STEPS,
  writeScope: 'offline_access accounting.transactions',
} }];

const input = $('Validate Connection Input').first().json;
const probe = $('Read Xero Probe').first().json;
const writeProbe = $input.first().json;

const NEXT = {
  connected: 'Tell the user which organisation it is connected to. Nothing more is needed to start a review.',
  not_connected: 'Walk the user through connecting it. Read the steps out one at a time and wait for them; it is a few minutes of clicking in another window, and the first time also needs a Xero developer app. You cannot do any of it for them, and there is no way to make the Xero sign-in window appear from this chat.',
  needs_reauth: 'Tell the user to reopen the Xero (read-only) credential in n8n and select Connect my account again. A Xero refresh token expires after 60 days without use, so this is normal after a quiet couple of months.',
  unknown: 'Say it could not be checked right now and offer to try again. Do not tell the user to reconfigure anything on the strength of one failed check.',
};

const WRITE_NEXT = {
  connected: 'The write credential is connected too, so prepare_green_matches is available once they have accepted some suggestions.',
  not_connected: 'The optional write credential is not set up. Only mention it if the user asks about preparing transactions in Xero; everything else works without it.',
  needs_reauth: 'The optional write credential needs reconnecting the same way. Only mention it if the user wants to prepare transactions.',
  unknown: '',
};

return [{ json: { ...input, response: {
  ok: true,
  connected: probe.connected,
  state: probe.state,
  organisationName: probe.organisationName,
  tenantId: probe.tenantId,
  organisationCount: probe.organisationCount,
  multipleOrganisations: probe.organisationCount > 1,
  n8nUrl: probe.n8nUrl,
  connectSteps: probe.connectSteps,
  requiredScope: probe.scope,
  message: probe.message + (probe.organisationCount > 1 ? ' More than one organisation is authorised; reviews use the first one.' : ''),
  nextStep: NEXT[probe.state] ?? NEXT.unknown,
  writeConnected: writeProbe.writeConnected,
  writeState: writeProbe.writeState,
  writeConnectSteps: writeProbe.writeConnectSteps,
  writeScope: writeProbe.writeScope,
  writeNextStep: WRITE_NEXT[writeProbe.writeState] ?? '',
} } }];

const input = $('Validate Connection Input').first().json;
const response = $json.response ?? { ok: false, error: { code: 'TOOL_FAILED', message: 'The tool did not return a result.' } };
return { json: {
  occurredAt: new Date().toISOString(),
  sessionId: input.sessionId,
  requestId: input.requestId,
  toolName: 'check_xero_connection',
  proposedInput: JSON.stringify(input.proposedInput ?? {}),
  result: JSON.stringify(response),
  error: response.ok === false ? String(response.error?.message ?? 'Tool failed') : '',
  response
} };

const prepared = $('Prepare Audit').first().json;
const response = { ...prepared.response };
if (!Number.isInteger($json.id)) {
  response.auditWarning = 'The tool result could not be written to the local audit table.';
}
return { json: response };
